record.field:
config = model.next() or {}
if config.get('type') not in ('ir.actions.act_window_close',):
    action = config

tag_deprecated = env.ref('documents.documents_tag_deprecated', raise_if_not_found=False)
if tag_deprecated and tag_deprecated in records.tag_ids:
    raise UserError(env._("Impossible to mark documents as Deprecated twice."))
tag_draft = env.ref('documents.documents_tag_draft', raise_if_not_found=False)
if tag_draft and tag_draft in records.tag_ids:
    raise UserError(env._("Impossible to deprecate documents marked as Draft."))

failures = env['ir.demo_failure'].search([
    ('wizard_id', '=', False),
])
record = model.create({
    'failure_ids': [Command.set(failures.ids)],
})
action = {
    'type': 'ir.actions.act_window',
    'res_id': record.id,
    'res_model': 'ir.demo_failure.wizard',
    'target': 'new',
    'views': [(env.ref('base.demo_failures_dialog').id, 'form')],
}

target = env.ref('documents.document_finance_folder', raise_if_not_found=False)
if target:
    permissions = records.mapped('user_permission')
    records.action_move_documents(target.id)
    for record, permission in zip(records, permissions):
        record.sudo().action_update_access_rights(partners={env.user.partner_id: (permission, None)})
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'message': env._("%(nb_records)s document(s) sent to Finance", nb_records=len(records)),
            'type': 'success',
        }
    }

if records:
    res = records.button_validate()
    if isinstance(res, dict):
        action = res

# Available variables: # - env: environment on which the action is triggered # - model: model of the record on which the action is triggered; is a void recordset # - record: record on which the action is triggered; may be void # - records: recordset of all records on which the action is triggered in multi-mode; may be void # - time, datetime, dateutil, timezone: useful Python libraries # - float_compare: utility function to compare floats based on specific precision # - b64encode, b64decode: functions to encode/decode binary data # - log: log(message, level='info'): logging function to record debug information in ir.logging table # - _logger: _logger.info(message): logger to emit messages in server logs # - UserError: exception class for raising user-facing warning messages # - Command: x2many commands namespace # To return an action, assign: action = {...}
sale_order = env['sale.order'].search([('x_studio_pet', '=', record.id)], limit=1)
if not sale_order: # Create a demo sale order if none exists sale_order = env['sale.order'].create({ 'partner_id': record.x_pets_id.x_studio_owner.id, 'x_studio_pet': record.id, })
# Manually pass order_id in the context before calling the method ctx = dict(env.context, order_id=sale_order.id) action = record.env['sale.order.line'].with_context(ctx).action_add_from_catalog()

